CREATE TABLE public.payouts (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, amount_cents INTEGER NOT NULL CHECK (amount_cents > 0), created_by UUID REFERENCES auth.users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()); GRANT SELECT, INSERT ON public.payouts TO authenticated; GRANT ALL ON public.payouts TO service_role; ALTER TABLE public.payouts ENABLE ROW LEVEL SECURITY; CREATE POLICY "Mitarbeiter sehen eigene Auszahlungen" ON public.payouts FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY "Admins sehen alle Auszahlungen" ON public.payouts FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role)); CREATE POLICY "Admins legen Auszahlungen an" ON public.payouts FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'::app_role)); CREATE TRIGGER update_payouts_updated_at BEFORE UPDATE ON public.payouts FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();